command:
timeout 110 bash -c 'node --input-type=module <<'\''NODE'\''
process.env.CREW_DATA_DIR='\''data/w2-work-proof'\'';
const runtime=await import(new URL('\''./scripts/acceptance-runtime.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const work=await import(new URL('\''./scripts/checks/work.mjs'\'','\''file://'\''+process.cwd()+'\''/'\''));
const ids=await runtime.load('\''acceptance-state.json'\'');const checks=[];const server=await runtime.startServer();
try { const ctx=runtime.createContext(server.url,ids,checks,{readOnly:true});await work.remount(ctx);await work.restart(ctx);console.log(JSON.stringify({ok:true,checks,actualNewWorkspace:true})); }
finally {await server.stop();}
NODE
'

